def row(i,parent=None,cat=False,dog=False):
    return {"id":i,"parent_comment":parent,"body":"text","cat":cat,"dog":dog}
comments={i:row(i,i-1 if i else None,dog=(i==4)) for i in range(12)}
assert get_comments_to_exclude(comments,"CAT_PERSON") == set(range(4,12))
assert get_comments_to_exclude(comments,"DOG_PERSON") == set()

def row(i,parent=None,cat=False,dog=False):
    return {"id":i,"parent_comment":parent,"body":"text","cat":cat,"dog":dog}
rows=[row(3,2),row(2,1,dog=True),row(4,1,cat=True),row(1)]
comments={item["id"]:item for item in rows}
assert get_comments_to_exclude(comments,"CAT_PERSON") == {2,3}
assert get_comments_to_exclude(comments,"DOG_PERSON") == {4}

def row(i,parent=None,cat=False,dog=False):
    return {"id":i,"parent_comment":parent,"body":"text","cat":cat,"dog":dog}
assert get_comments_to_exclude({},"CAT_PERSON") == set()
comments={1:row(1),2:row(2)}
assert get_comments_to_exclude(comments,"CAT_PERSON") == set()
assert get_comments_to_exclude(comments,"DOG_PERSON") == set()

def row(i,parent=None,cat=False,dog=False):
    return {"id":i,"parent_comment":parent,"body":"text","cat":cat,"dog":dog}
import copy
comments={1:row(1),2:row(2,1,dog=True),3:row(3,2)}
before=copy.deepcopy(comments)
assert get_comments_to_exclude(comments,"CAT_PERSON") == {2,3}
assert get_comments_to_exclude(comments,"DOG_PERSON") == set()
assert comments == before
